"""Frozen contract: merge integer half-open ranges (MATRIX_SPEC.md)."""

def merge_ranges(spans):
    """Validate, sort and coalesce [start, end) ranges.

    Returns a new list of two-element lists. Never mutates the input.
    """
    if not isinstance(spans, (list, tuple)):
        raise ValueError("spans must be a list or tuple")

    validated = []
    for pair in spans:
        if not isinstance(pair, (list, tuple)) or len(pair) != 2:
            raise ValueError("each span must be a list or tuple pair")
        start, end = pair
        if isinstance(start, bool) or not isinstance(start, int):
            raise ValueError("span start must be an integer excluding bool")
        if isinstance(end, bool) or not isinstance(end, int):
            raise ValueError("span end must be an integer excluding bool")
        if start > end:
            raise ValueError("span start must not exceed end")
        validated.append((start, end))

    ordered = sorted((start, end) for start, end in validated if start < end)

    merged = []
    for start, end in ordered:
        if merged and start <= merged[-1][1]:
            if end > merged[-1][1]:
                merged[-1][1] = end
        else:
            merged.append([start, end])
    return merged

"""Frozen contract: parse escaped, comma-separated tags (MATRIX_SPEC.md)."""

def parse_tags(text):
    """Split on unescaped commas, decode escapes, strip, casefold, dedupe."""
    if not isinstance(text, str):
        raise ValueError("text must be a str")

    for char in text:
        if char < " " or char == "\x7f":
            raise ValueError("control characters are not allowed")

    segments = []
    current = []
    index = 0
    length = len(text)
    while index < length:
        char = text[index]
        if char == "\\":
            if index + 1 >= length:
                raise ValueError("trailing escape")
            escaped = text[index + 1]
            if escaped not in (",", "\\"):
                raise ValueError("unknown escape")
            current.append(escaped)
            index += 2
        elif char == ",":
            segments.append("".join(current))
            current = []
            index += 1
        else:
            current.append(char)
            index += 1
    segments.append("".join(current))

    result = []
    seen = set()
    for segment in segments:
        value = segment.strip().casefold()
        if value and value not in seen:
            seen.add(value)
            result.append(value)
    return result
